import assert from 'node:assert/strict';
const pages=await(await fetch('http://127.0.0.1:9222/json')).json();
const ws=new WebSocket(pages.find(p=>p.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
let id=0;const pending=new Map();ws.onmessage=({data})=>{const m=JSON.parse(data);if(pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(Error(JSON.stringify(m.error))):p.resolve(m.result);}};
const send=(method,params={})=>new Promise((resolve,reject)=>{pending.set(++id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
const evaluate=async expression=>{const r=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,userGesture:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;};
try {
 await send('Page.navigate',{url:'http://127.0.0.1:3001/'});await new Promise(r=>setTimeout(r,350));
 const result=await evaluate(`(async()=>{
 const {scheduleDamageSound,DAMAGE_AUDIO_PROFILES}=await import('/src/js/toy-room/DamageAudio.js');
 const results=[];
 for(const actor of Object.keys(DAMAGE_AUDIO_PROFILES))for(const arena of [false,true]) {
  const ctx=new OfflineAudioContext(1,44100,44100),nodes=[];
  scheduleDamageSound(ctx,ctx.destination,node=>nodes.push(node),actor,arena);
  const buffer=await ctx.startRendering(),data=buffer.getChannelData(0);
  let peak=0,sum=0,tail=0;for(let i=0;i<data.length;i++){peak=Math.max(peak,Math.abs(data[i]));sum+=data[i]*data[i];if(i>22050)tail=Math.max(tail,Math.abs(data[i]));}
  results.push({actor,arena,peak,rms:Math.sqrt(sum/data.length),tail,voices:nodes.length});
 }
 const {createAudioSystem}=await import('/src/js/audio.js');const audio=createAudioSystem();
 // Contexto real desbloqueado pela interação; a saída é encaminhada ao ganho mestre.
 audio.initAudio();const played=audio.playArenaSound('player_hit');audio.setMuted(true);
 const muted=audio.getMasterVolume();audio.clearActiveSounds();
 return {results,played,volume:muted};
 })()`);
 for(const r of result.results){assert.ok(r.peak>0.02&&r.peak<0.95,'Sinal audível sem clipping: '+JSON.stringify(r));assert.ok(r.rms>0.002);assert.ok(r.tail<0.0001,'Cauda encerra sem vazamento');assert.equal(r.voices,4);}
 assert.equal(result.played,true,'Evento público de dano agenda áudio real');
 console.log('APROVADO: dez renderizações offline de impacto/dor, cinco timbres, arena/exploração, sinal sem clipping e cauda encerrada; evento player_hit integrado ao áudio real.');
 console.log(JSON.stringify(result.results));
} finally {ws.close();}
